INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('gasheizung-mietwohnung-tausch-2065-global-2000-gaswirtschaftsgesetz','Gasheizung in Mietwohnungen: Tausch dauert laut GLOBAL 2000 bis 2065','Rund 844.000 Gasheizungen sind in Österreichs Wohnungen noch in Betrieb, meist in Mietwohnungen. GLOBAL 2000 warnt: Beim aktuellen Tempo dauert der Umstieg bis 2065.','Die **Gasheizung in der Mietwohnung** bleibt für Hunderttausende Haushalte in Österreich vorerst Realität: Darauf weist die Umweltschutzorganisation GLOBAL 2000 in einer Aussendung vom 27. Oktober 2026 hin. Anlass ist der Start des neuen Fördercalls für den Heizkesseltausch am 2. November. Die NGO begrüßt die Förderung grundsätzlich, sieht aber große Lücken bei den rechtlichen Rahmenbedingungen – vor allem für Mieterinnen und Mieter.

## Neue Sanierungsförderung startet am 2. November

Für den Tausch alter Heizkessel stellt die Bundesregierung bis Jahresende knapp 20 Millionen Euro bereit. Ab Anfang Jänner 2027 soll die neue Sanierungsoffensive dann in vollem Umfang anlaufen. Wer ein Eigenheim besitzt, kann damit den Umstieg von Gas oder Öl auf ein klimafreundliches System finanziell abfedern.

Für Haushalte in Mehrparteienhäusern sieht die Lage laut GLOBAL 2000 anders aus. Wer zur Miete wohnt, kann nicht allein entscheiden, ob die Heizung getauscht wird. Ohne eine Änderung der gesetzlichen Grundlagen hätten diese Haushalte von der Förderung daher kaum etwas, kritisiert die Organisation.

## Gasheizung in der Mietwohnung: 844.000 Geräte im Bestand

Nach Angaben von GLOBAL 2000 sind in österreichischen Wohngebäuden derzeit noch rund 844.000 Gasheizungen in Betrieb. Der Großteil davon befindet sich in Mietwohnungen. Pro Jahr werden laut der NGO derzeit etwa 20.300 dieser Anlagen ersetzt.

Rechnet man dieses Tempo hoch, wäre der Umstieg erst im Jahr 2065 abgeschlossen. Damit wären aus Sicht der Organisation weder das Ziel der Klimaneutralität 2040 noch jenes für 2050 erreichbar.

## Gaspreis und Netzgebühren steigen

Zusätzlich verweist GLOBAL 2000 auf die Kostenentwicklung. Der Großhandelspreis für Gas sei von rund 33,8 Euro pro Megawattstunde im Februar auf 89,6 Euro im Oktober gestiegen – also auf mehr als das Doppelte. Bei den Endkundinnen und Endkunden komme ein solcher Anstieg in der Regel mit zeitlicher Verzögerung an.

Auch die Gasnetzgebühren seien heuer um 18 Prozent gestiegen. Die NGO führt das auf die schleppende und unkoordinierte Umstellung zurück: Je weniger Haushalte am Gasnetz hängen, desto stärker müssten die verbleibenden Kundinnen und Kunden für ein zu groß gewordenes Netz aufkommen.

## Forderung nach neuem Gaswirtschaftsgesetz

Kern der Kritik ist das Fehlen eines neuen Gaswirtschaftsgesetzes. Nur damit ließen sich ganze Stadtteile oder Wohngebiete geplant und kostengünstig von Gas auf andere Heizformen umstellen, argumentiert Johannes Wahlmüller, Klima- und Energiesprecher von GLOBAL 2000. Ohne eine solche Reform drohe ein teures Flickwerk aus Einzellösungen. Die Verantwortung sieht die Organisation bei Wirtschaftsminister Wolfgang Hattmannsdorfer, von dem sie „Taten statt Worte“ verlangt.

Hinzu kommt ein Verfahren der EU-Kommission: Gegen Österreich läuft ein Vertragsverletzungsverfahren, weil das EU-Gaspaket nicht fristgerecht umgesetzt wurde. Dieses sieht vor, dass die Mitgliedstaaten bis 5. August 2026 Regeln für eine koordinierte Stilllegung von Gasnetzen schaffen.

Die Forderungen von GLOBAL 2000 im Überblick:

- ein neues Gaswirtschaftsgesetz, das die Umstellung ganzer Gebiete ermöglicht
- eine rasche Umsetzung des EU-Gaspakets
- rechtliche Grundlagen, damit auch Mieterinnen und Mieter vom Heizungstausch profitieren

## Was Eigentümer jetzt tun können

Für Hausbesitzerinnen und Hausbesitzer mit eigener Gas- oder Ölheizung ist der Fördercall ab 2. November die nächste Gelegenheit, einen Kesseltausch zu planen. Sinnvoll ist es, vorab ein Angebot eines Fachbetriebs einzuholen und zu klären, welches System – etwa Wärmepumpe, Fernwärme oder Biomasse – für das eigene Gebäude in Frage kommt. In Mehrparteienhäusern lohnt sich das Gespräch mit Hausverwaltung und Eigentümergemeinschaft, um gemeinsame Lösungen auszuloten.','bauen-wohnen','Sanieren',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/gasheizung-mietwohnung-tausch-2065-global-2000-gaswirtschaftsgesetz.webp','GLOBAL 2000 via APA-OTS','https://www.ots.at/presseaussendung/OTS_20261027_OTS0001/neue-sanierungsfoerderung-gas-ausstieg-im-schneckentempo','published','2026-10-27T14:50:00.000Z','2026-10-27T14:48:29.649Z','Gasheizung in Mietwohnungen: Umstieg erst 2065?','Gasheizung in der Mietwohnung: 844.000 Geräte sind noch in Betrieb. GLOBAL 2000 kritisiert die neue Sanierungsförderung – alle Fakten hier lesen.','Gasheizung Mietwohnung','["Gasheizung Mietwohnung","Gasheizung tauschen","Heizkesseltausch","Sanierungsoffensive 2027","Gaswirtschaftsgesetz Österreich","Gasheizung Mieter Förderung","Gasnetzgebühren 2026","Raus aus Gas Österreich","GLOBAL 2000 Gasausstieg"]','Gasheizung in einer Mietwohnung in einem Wiener Altbau','Old wall-mounted gas boiler in the narrow kitchen of a Viennese Altbau rental apartment, high ceiling, tiled wall, radiator below a tall window, soft late-autumn afternoon light, realistic documentary photo','[{"q":"Wie viele Gasheizungen gibt es noch in Österreichs Wohnungen?","a":"Laut GLOBAL 2000 sind rund 844.000 Gasheizungen in Wohngebäuden in Betrieb, die meisten davon in Mietwohnungen."},{"q":"Wann startet die neue Förderung für den Heizkesseltausch?","a":"Der Fördercall startet am 2. November 2026 mit knapp 20 Millionen Euro bis Jahresende, die volle Sanierungsoffensive soll Anfang Jänner 2027 anlaufen."},{"q":"Können Mieter ihre Gasheizung selbst tauschen lassen?","a":"Nein, Mieterinnen und Mieter können nicht allein über einen Heizungstausch entscheiden. GLOBAL 2000 fordert deshalb neue gesetzliche Grundlagen."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
